 * @returns {string} Relative path, empty when the two are the same.
 */
export function relative(from, to) {
  // Check argument types
  if (typeof from !== 'string') {
    throw new PathError('NOT_A_STRING', 'path must be a string');
  }

  if (typeof to !== 'string') {
    throw new PathError('NOT_A_STRING', 'path must be a string');
  }

  // Check for NUL bytes
  if (from.includes('\u0000')) {
    throw new PathError('NUL_BYTE', 'path contains a NUL byte');
  }

  if (to.includes('\u0000')) {
    throw new PathError('NUL_BYTE', 'path contains a NUL byte');
  }

  // Check if both paths are absolute
  if (!from.startsWith('/')) {
    throw new PathError('NOT_ABSOLUTE', 'both paths must be absolute');
  }

  if (!to.startsWith('/')) {
    throw new PathError('NOT_ABSOLUTE', 'both paths must be absolute');
  }

  // Normalize both paths (this may throw ESCAPE)
  const fromNorm = normalize(from);
  const toNorm = normalize(to);

  // Split into segments
  const fromSegments = fromNorm === '/' ? [] : fromNorm.slice(1).split('/');
  const toSegments = toNorm === '/' ? [] : toNorm.slice(1).split('/');

  // Find common prefix
  let commonLength = 0;
  const minLength = Math.min(fromSegments.length, toSegments.length);

  for (let i = 0; i < minLength; i++) {
    if (fromSegments[i] === toSegments[i]) {
      commonLength++;
    } else {
      break;
    }
  }

  // Build relative path
  const upSteps = fromSegments.length - commonLength;
  const downSteps = toSegments.slice(commonLength);

  const result = [];
  for (let i = 0; i < upSteps; i++) {
    result.push('..');
  }
  result.push(...downSteps);

  return result.join('/') || '';
}

